'use client';

import {
  defaultEmojiDataResolver,
  type EmojiData,
  type EmojiDataResolver,
  type EmojiDetails,
} from 'frimousse';
import * as React from 'react';

/**
 * Pinned Emojibase release. To self-host, serve `en/data.json`,
 * `en/messages.json` and `en/shortcodes/github.json` from this release and
 * point this URL at them.
 */
const EMOJIBASE_URL = 'https://cdn.jsdelivr.net/npm/emojibase-data@17.0.0';
const SHORTCODES_KEY = 'plate:emoji-shortcodes@17.0.0';
const MAX_RESULTS = 60;
const TRAILING_COLON = /:$/;
const VARIATION_SELECTOR = /^FE0[EF]$/;

/** An Emojibase emoji with the GitHub shortcodes people type after `:`. */
export type EmojiEntry = EmojiDetails & { shortcodes: readonly string[] };

type EmojiCatalog = EmojiData & { emojis: EmojiEntry[] };

/** The loaded entries, or the state of the load. */
export type EmojiStatus = readonly EmojiEntry[] | 'failed' | 'loading';

// Shortcode files key emoji by hexcode, frimousse keeps only the glyph, and
// the two disagree on variation selectors, so both sides drop them.
const glyphKey = (emoji: string) =>
  Array.from(emoji, (char) =>
    char.codePointAt(0)!.toString(16).toUpperCase().padStart(4, '0')
  )
    .filter((code) => !VARIATION_SELECTOR.test(code))
    .join('-');

const hexcodeKey = (hexcode: string) =>
  hexcode
    .split('-')
    .filter((code) => !VARIATION_SELECTOR.test(code))
    .join('-');

function parseShortcodes(value: unknown) {
  if (typeof value !== 'object' || value === null || !('1F604' in value)) {
    return null;
  }

  const shortcodes = new Map<string, readonly string[]>();

  for (const [hexcode, codes] of Object.entries(value)) {
    if (typeof codes === 'string') {
      shortcodes.set(hexcodeKey(hexcode), [codes]);
    } else if (
      Array.isArray(codes) &&
      codes.every((code) => typeof code === 'string')
    ) {
      shortcodes.set(hexcodeKey(hexcode), codes);
    } else {
      return null;
    }
  }

  return shortcodes;
}

function readStoredShortcodes() {
  try {
    const stored = localStorage.getItem(SHORTCODES_KEY);

    return stored ? parseShortcodes(JSON.parse(stored)) : null;
  } catch {
    return null;
  }
}

async function loadShortcodes() {
  const stored = readStoredShortcodes();

  if (stored) return stored;

  const response = await fetch(`${EMOJIBASE_URL}/en/shortcodes/github.json`);

  if (!response.ok) {
    throw new Error(`Emoji shortcodes failed to load (${response.status}).`);
  }

  const json: unknown = await response.json();
  const shortcodes = parseShortcodes(json);

  if (!shortcodes) throw new Error('Emoji shortcodes are malformed.');

  try {
    localStorage.setItem(SHORTCODES_KEY, JSON.stringify(json));
  } catch {
    // Blocked or full storage only costs a refetch on the next page load.
  }

  return shortcodes;
}

let loading: Promise<EmojiCatalog> | undefined;

/**
 * Loads Emojibase once per page through frimousse, which caches it and drops
 * emoji the device cannot draw, and joins GitHub shortcodes to it. A failed
 * load is forgotten, so the next call retries.
 */
function loadEmojis() {
  loading ??= Promise.all([
    defaultEmojiDataResolver('en', { emojibaseUrl: EMOJIBASE_URL }),
    loadShortcodes(),
  ]).then(
    ([data, shortcodes]): EmojiCatalog => ({
      ...data,
      emojis: data.emojis.map((emoji) => ({
        ...emoji,
        shortcodes: shortcodes.get(glyphKey(emoji.emoji)) ?? [],
      })),
    }),
    (error: unknown) => {
      loading = undefined;
      throw error;
    }
  );

  return loading;
}

/**
 * The data source for frimousse pickers. Mount a picker only once
 * `useEmojis` reports entries, so this resolves from the loaded catalog.
 */
export const resolveEmojiData: EmojiDataResolver = () => loadEmojis();

let status: EmojiStatus = 'loading';
let requested = false;
const listeners = new Set<() => void>();

const setStatus = (next: EmojiStatus) => {
  status = next;
  listeners.forEach((listener) => listener());
};

function requestEmojis() {
  if (requested && status !== 'failed') return;

  requested = true;

  if (status === 'failed') setStatus('loading');

  loadEmojis().then(
    (catalog) => setStatus(catalog.emojis),
    () => setStatus('failed')
  );
}

const subscribe = (listener: () => void) => {
  listeners.add(listener);

  return () => listeners.delete(listener);
};

/**
 * Shared emoji entries for the `:` popup and the pickers. A non-null query
 * starts the load; after a failure, each new query retries it.
 */
export function useEmojis(query: string | null): EmojiStatus {
  const current = React.useSyncExternalStore(
    subscribe,
    () => status,
    () => 'loading' as const
  );

  React.useEffect(() => {
    if (query !== null) requestEmojis();
  }, [query]);

  return current;
}

type IndexedEntry = {
  entry: EmojiEntry;
  shortcodes: readonly string[];
  text: string;
  words: readonly string[];
};

const indexes = new WeakMap<readonly EmojiEntry[], IndexedEntry[]>();

function getIndex(entries: readonly EmojiEntry[]) {
  let index = indexes.get(entries);

  if (!index) {
    index = entries.map((entry) => {
      const label = entry.label.toLowerCase();
      const shortcodes = entry.shortcodes.map((code) => code.toLowerCase());

      return {
        entry,
        shortcodes,
        text: [label, ...entry.tags, ...shortcodes].join(',').toLowerCase(),
        words: label.split(' '),
      };
    });
    indexes.set(entries, index);
  }

  return index;
}

// Called only for entries whose text holds the query, so the last rank is a
// substring match.
const rank = ({ shortcodes, words }: IndexedEntry, query: string) => {
  if (shortcodes.includes(query)) return 0;

  let shortest = Infinity;

  for (const code of shortcodes) {
    if (code.startsWith(query)) shortest = Math.min(shortest, code.length);
  }

  // The shortest shortcode wins, so the top result stays put while the query
  // grows toward it: `smil` ranks `smile` before `smiley`.
  if (shortest !== Infinity) return 1 + shortest / 1000;
  if (words.some((word) => word.startsWith(query))) return 2;

  return 3;
};

/**
 * Ranks entries for a query typed after `:` or in a picker: an exact
 * shortcode, then a shortcode prefix, then a label word prefix, then any
 * substring of the label, tags or shortcodes. One trailing `:` is ignored.
 */
export function searchEmojis(
  entries: readonly EmojiEntry[],
  query: string
): EmojiEntry[] {
  const search = query.toLowerCase().replace(TRAILING_COLON, '');

  if (!search) return [];

  const index = getIndex(entries);
  const matches: { entry: EmojiEntry; order: number; rank: number }[] = [];

  for (let order = 0; order < index.length; order++) {
    const indexed = index[order];

    if (indexed.text.includes(search)) {
      matches.push({ entry: indexed.entry, order, rank: rank(indexed, search) });
    }
  }

  matches.sort((a, b) => a.rank - b.rank || a.order - b.order);

  return matches.slice(0, MAX_RESULTS).map((match) => match.entry);
}
